/* 
  Anatomy of an HTTP POST Request:
*/

// 1. REQUEST LINE (Method, Path, Protocol Version)
POST /api/users/create HTTP/1.1

// 2. HEADERS (Key-Value pairs providing metadata)
Host: myapi.com
Content-Type: application/json
Authorization: Bearer my_secret_token_123
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X)

// 3. BLANK LINE (Mandatory to separate headers from body)

// 4. BODY (The actual data being sent to the server)
{
  "username": "johndoe",
  "age": 25
}
